Based on the commit message, the root cause and the patch provided below, you need to:

1. explain how the bug occurs, including all code statements that are most likely to lead to the bug and why. 
2. explain how the bug is fixed, including code statements fixing the bug and why. 

You must include one or more code statements in point 1 and 2.
Code statements included in point 1 should be as brief as possible, only include the ones that are most related to the root cause and  the number of code statements may not exceed 3.


Here is the commit message:
drm/amdgpu/userq: Fix reference leak in
 amdgpu_userq_wait_ioctl
MIME-Version: 1.0
Content-Type: text/plain; charset=UTF-8
Content-Transfer-Encoding: 8bit

Drop reference to syncobj and timeline fence when aborting the ioctl due
output array being too small.

Reviewed-by: Alex Deucher <alexander.deucher@amd.com>
Signed-off-by: Tvrtko Ursulin <tvrtko.ursulin@igalia.com>
Fixes: a292fdecd728 ("drm/amdgpu: Implement userqueue signal/wait IOCTL")
Cc: Arunpravin Paneer Selvam <Arunpravin.PaneerSelvam@amd.com>
Cc: Christian König <christian.koenig@amd.com>
Cc: Alex Deucher <alexander.deucher@amd.com>
Signed-off-by: Alex Deucher <alexander.deucher@amd.com>
(cherry picked from commit 68951e9c3e6bb22396bc42ef2359751c8315dd27)
Cc: <stable@vger.kernel.org> # v6.16+

Here is the root cause:
In amdgpu_userq_wait_ioctl, when the output array size check fails (num_fences >= wait_info->num_fences), the code jumps to the free_fences label without releasing the fence reference that was acquired earlier (either from an unwrapped chain or directly from an array), causing a reference leak.

Here is the patch:

 int amdgpu_userq_wait_ioctl(struct drm_device *dev, void *data,
 			    struct drm_file *filp)
 {
 	u32 *syncobj_handles, *timeline_points, *timeline_handles, *bo_handles_read, *bo_handles_write;
 	u32 num_syncobj, num_read_bo_handles, num_write_bo_handles;
 	struct drm_amdgpu_userq_fence_info *fence_info = NULL;
 	struct drm_amdgpu_userq_wait *wait_info = data;
 	struct amdgpu_fpriv *fpriv = filp->driver_priv;
 	struct amdgpu_userq_mgr *userq_mgr = &fpriv->userq_mgr;
 	struct amdgpu_usermode_queue *waitq;
 	struct drm_gem_object **gobj_write;
 	struct drm_gem_object **gobj_read;
 	struct dma_fence **fences = NULL;
 	u16 num_points, num_fences = 0;
 	int r, i, rentry, wentry, cnt;
 	struct drm_exec exec;

 	if (!amdgpu_userq_enabled(dev))
 		return -ENOTSUPP;

 	num_read_bo_handles = wait_info->num_bo_read_handles;
 	bo_handles_read = memdup_user(u64_to_user_ptr(wait_info->bo_read_handles),
 				      size_mul(sizeof(u32), num_read_bo_handles));
 	if (IS_ERR(bo_handles_read))
 		return PTR_ERR(bo_handles_read);

 	num_write_bo_handles = wait_info->num_bo_write_handles;
 	bo_handles_write = memdup_user(u64_to_user_ptr(wait_info->bo_write_handles),
 				       size_mul(sizeof(u32), num_write_bo_handles));
 	if (IS_ERR(bo_handles_write)) {
 		r = PTR_ERR(bo_handles_write);
 		goto free_bo_handles_read;
 	}

 	num_syncobj = wait_info->num_syncobj_handles;
 	syncobj_handles = memdup_user(u64_to_user_ptr(wait_info->syncobj_handles),
 				      size_mul(sizeof(u32), num_syncobj));
 	if (IS_ERR(syncobj_handles)) {
 		r = PTR_ERR(syncobj_handles);
 		goto free_bo_handles_write;
 	}

 	num_points = wait_info->num_syncobj_timeline_handles;
 	timeline_handles = memdup_user(u64_to_user_ptr(wait_info->syncobj_timeline_handles),
 				       sizeof(u32) * num_points);
 	if (IS_ERR(timeline_handles)) {
 		r = PTR_ERR(timeline_handles);
 		goto free_syncobj_handles;
 	}

 	timeline_points = memdup_user(u64_to_user_ptr(wait_info->syncobj_timeline_points),
 				      sizeof(u32) * num_points);
 	if (IS_ERR(timeline_points)) {
 		r = PTR_ERR(timeline_points);
 		goto free_timeline_handles;
 	}

 	gobj_read = kmalloc_array(num_read_bo_handles, sizeof(*gobj_read), GFP_KERNEL);
 	if (!gobj_read) {
 		r = -ENOMEM;
 		goto free_timeline_points;
 	}

 	for (rentry = 0; rentry < num_read_bo_handles; rentry++) {
 		gobj_read[rentry] = drm_gem_object_lookup(filp, bo_handles_read[rentry]);
 		if (!gobj_read[rentry]) {
 			r = -ENOENT;
 			goto put_gobj_read;
 		}
 	}

 	gobj_write = kmalloc_array(num_write_bo_handles, sizeof(*gobj_write), GFP_KERNEL);
 	if (!gobj_write) {
 		r = -ENOMEM;
 		goto put_gobj_read;
 	}

 	for (wentry = 0; wentry < num_write_bo_handles; wentry++) {
 		gobj_write[wentry] = drm_gem_object_lookup(filp, bo_handles_write[wentry]);
 		if (!gobj_write[wentry]) {
 			r = -ENOENT;
 			goto put_gobj_write;
 		}
 	}

 	drm_exec_init(&exec, DRM_EXEC_INTERRUPTIBLE_WAIT,
 		      (num_read_bo_handles + num_write_bo_handles));

 	/* Lock all BOs with retry handling */
 	drm_exec_until_all_locked(&exec) {
 		r = drm_exec_prepare_array(&exec, gobj_read, num_read_bo_handles, 1);
 		drm_exec_retry_on_contention(&exec);
 		if (r) {
 			drm_exec_fini(&exec);
 			goto put_gobj_write;
 		}

 		r = drm_exec_prepare_array(&exec, gobj_write, num_write_bo_handles, 1);
 		drm_exec_retry_on_contention(&exec);
 		if (r) {
 			drm_exec_fini(&exec);
 			goto put_gobj_write;
 		}
 	}

 	if (!wait_info->num_fences) {
 		if (num_points) {
 			struct dma_fence_unwrap iter;
 			struct dma_fence *fence;
 			struct dma_fence *f;

 			for (i = 0; i < num_points; i++) {
 				r = drm_syncobj_find_fence(filp, timeline_handles[i],
 							   timeline_points[i],
 							   DRM_SYNCOBJ_WAIT_FLAGS_WAIT_FOR_SUBMIT,
 							   &fence);
 				if (r)
 					goto exec_fini;

 				dma_fence_unwrap_for_each(f, &iter, fence)
 					num_fences++;

 				dma_fence_put(fence);
 			}
 		}

 		/* Count syncobj's fence */
 		for (i = 0; i < num_syncobj; i++) {
 			struct dma_fence *fence;

 			r = drm_syncobj_find_fence(filp, syncobj_handles[i],
 						   0,
 						   DRM_SYNCOBJ_WAIT_FLAGS_WAIT_FOR_SUBMIT,
 						   &fence);
 			if (r)
 				goto exec_fini;

 			num_fences++;
 			dma_fence_put(fence);
 		}

 		/* Count GEM objects fence */
 		for (i = 0; i < num_read_bo_handles; i++) {
 			struct dma_resv_iter resv_cursor;
 			struct dma_fence *fence;

 			dma_resv_for_each_fence(&resv_cursor, gobj_read[i]->resv,
 						DMA_RESV_USAGE_READ, fence)
 				num_fences++;
 		}

 		for (i = 0; i < num_write_bo_handles; i++) {
 			struct dma_resv_iter resv_cursor;
 			struct dma_fence *fence;

 			dma_resv_for_each_fence(&resv_cursor, gobj_write[i]->resv,
 						DMA_RESV_USAGE_WRITE, fence)
 				num_fences++;
 		}

 		/*
 		 * Passing num_fences = 0 means that userspace doesn't want to
 		 * retrieve userq_fence_info. If num_fences = 0 we skip filling
 		 * userq_fence_info and return the actual number of fences on
 		 * args->num_fences.
 		 */
 		wait_info->num_fences = num_fences;
 	} else {
 		/* Array of fence info */
 		fence_info = kmalloc_array(wait_info->num_fences, sizeof(*fence_info), GFP_KERNEL);
 		if (!fence_info) {
 			r = -ENOMEM;
 			goto exec_fini;
 		}

 		/* Array of fences */
 		fences = kmalloc_array(wait_info->num_fences, sizeof(*fences), GFP_KERNEL);
 		if (!fences) {
 			r = -ENOMEM;
 			goto free_fence_info;
 		}

 		/* Retrieve GEM read objects fence */
 		for (i = 0; i < num_read_bo_handles; i++) {
 			struct dma_resv_iter resv_cursor;
 			struct dma_fence *fence;

 			dma_resv_for_each_fence(&resv_cursor, gobj_read[i]->resv,
 						DMA_RESV_USAGE_READ, fence) {
 				if (WARN_ON_ONCE(num_fences >= wait_info->num_fences)) {
 					r = -EINVAL;
 					goto free_fences;
 				}

 				fences[num_fences++] = fence;
 				dma_fence_get(fence);
 			}
 		}

 		/* Retrieve GEM write objects fence */
 		for (i = 0; i < num_write_bo_handles; i++) {
 			struct dma_resv_iter resv_cursor;
 			struct dma_fence *fence;

 			dma_resv_for_each_fence(&resv_cursor, gobj_write[i]->resv,
 						DMA_RESV_USAGE_WRITE, fence) {
 				if (WARN_ON_ONCE(num_fences >= wait_info->num_fences)) {
 					r = -EINVAL;
 					goto free_fences;
 				}

 				fences[num_fences++] = fence;
 				dma_fence_get(fence);
 			}
 		}

 		if (num_points) {
 			struct dma_fence_unwrap iter;
 			struct dma_fence *fence;
 			struct dma_fence *f;

 			for (i = 0; i < num_points; i++) {
 				r = drm_syncobj_find_fence(filp, timeline_handles[i],
 							   timeline_points[i],
 							   DRM_SYNCOBJ_WAIT_FLAGS_WAIT_FOR_SUBMIT,
 							   &fence);
 				if (r)
 					goto free_fences;

 				dma_fence_unwrap_for_each(f, &iter, fence) {
 					if (WARN_ON_ONCE(num_fences >= wait_info->num_fences)) {
 						r = -EINVAL;
+						dma_fence_put(fence);
 						goto free_fences;
 					}

 					dma_fence_get(f);
 					fences[num_fences++] = f;
 				}

 				dma_fence_put(fence);
 			}
 		}

 		/* Retrieve syncobj's fence */
 		for (i = 0; i < num_syncobj; i++) {
 			struct dma_fence *fence;

 			r = drm_syncobj_find_fence(filp, syncobj_handles[i],
 						   0,
 						   DRM_SYNCOBJ_WAIT_FLAGS_WAIT_FOR_SUBMIT,
 						   &fence);
 			if (r)
 				goto free_fences;

 			if (WARN_ON_ONCE(num_fences >= wait_info->num_fences)) {
 				r = -EINVAL;
+				dma_fence_put(fence);
 				goto free_fences;
 			}

 			fences[num_fences++] = fence;
 		}

 		/*
 		 * Keep only the latest fences to reduce the number of values
 		 * given back to userspace.
 		 */
 		num_fences = dma_fence_dedup_array(fences, num_fences);

 		waitq = xa_load(&userq_mgr->userq_xa, wait_info->waitq_id);
 		if (!waitq) {
 			r = -EINVAL;
 			goto free_fences;
 		}

 		for (i = 0, cnt = 0; i < num_fences; i++) {
 			struct amdgpu_userq_fence_driver *fence_drv;
 			struct amdgpu_userq_fence *userq_fence;
 			u32 index;

 			userq_fence = to_amdgpu_userq_fence(fences[i]);
 			if (!userq_fence) {
 				/*
 				 * Just waiting on other driver fences should
 				 * be good for now
 				 */
 				r = dma_fence_wait(fences[i], true);
 				if (r) {
 					dma_fence_put(fences[i]);
 					goto free_fences;
 				}

 				dma_fence_put(fences[i]);
 				continue;
 			}

 			fence_drv = userq_fence->fence_drv;
 			/*
 			 * We need to make sure the user queue release their reference
 			 * to the fence drivers at some point before queue destruction.
 			 * Otherwise, we would gather those references until we don't
 			 * have any more space left and crash.
 			 */
 			r = xa_alloc(&waitq->fence_drv_xa, &index, fence_drv,
 				     xa_limit_32b, GFP_KERNEL);
 			if (r)
 				goto free_fences;

 			amdgpu_userq_fence_driver_get(fence_drv);

 			/* Store drm syncobj's gpu va address and value */
 			fence_info[cnt].va = fence_drv->va;
 			fence_info[cnt].value = fences[i]->seqno;

 			dma_fence_put(fences[i]);
 			/* Increment the actual userq fence count */
 			cnt++;
 		}

 		wait_info->num_fences = cnt;
 		/* Copy userq fence info to user space */
 		if (copy_to_user(u64_to_user_ptr(wait_info->out_fences),
 				 fence_info, wait_info->num_fences * sizeof(*fence_info))) {
 			r = -EFAULT;
 			goto free_fences;
 		}

 		kfree(fences);
 		kfree(fence_info);
 	}

 	drm_exec_fini(&exec);
 	for (i = 0; i < num_read_bo_handles; i++)
 		drm_gem_object_put(gobj_read[i]);
 	kfree(gobj_read);

 	for (i = 0; i < num_write_bo_handles; i++)
 		drm_gem_object_put(gobj_write[i]);
 	kfree(gobj_write);

 	kfree(timeline_points);
 	kfree(timeline_handles);
 	kfree(syncobj_handles);
 	kfree(bo_handles_write);
 	kfree(bo_handles_read);

 	return 0;

 free_fences:
 	while (num_fences-- > 0)
 		dma_fence_put(fences[num_fences]);
 	kfree(fences);
 free_fence_info:
 	kfree(fence_info);
 exec_fini:
 	drm_exec_fini(&exec);
 put_gobj_write:
 	while (wentry-- > 0)
 		drm_gem_object_put(gobj_write[wentry]);
 	kfree(gobj_write);
 put_gobj_read:
 	while (rentry-- > 0)
 		drm_gem_object_put(gobj_read[rentry]);
 	kfree(gobj_read);
 free_timeline_points:
 	kfree(timeline_points);
 free_timeline_handles:
 	kfree(timeline_handles);
 free_syncobj_handles:
 	kfree(syncobj_handles);
 free_bo_handles_write:
 	kfree(bo_handles_write);
 free_bo_handles_read:
 	kfree(bo_handles_read);

 	return r;
 }
-- 


